export const glossary = [
 ['Goal','Your saved statement of the business question.'],['Plan','A versioned set of supported steps proposed for a goal.'],['Run','A record of steps actually attempted and their outcomes.'],['Opportunity','A research candidate with identity/context; not automatically a seller Product.'],['Product','Your owned product master used in supported preparation/operation workflows.'],['Catalog','The preparation workspace for owned products, variants, media, costs and local listing drafts.'],['SKU','Your stock-keeping code for a specific item or variant.'],['Variant','A distinct form of a product, such as a real size or colour.'],['MOQ','Minimum order quantity, known only when supported by supplier evidence.'],['Lead time','The evidenced or explicitly assumed time to supply; not a guaranteed delivery date.'],['Landed cost','Supported acquisition costs with included components, quantities/currency and missing inputs disclosed.'],['Margin','A calculated proportion under a specific model; read its basis, not just the percentage.'],['Capital fit','Whether a supported scenario fits the stated available funds under its known inputs.'],['UNKNOWN','A fact or result is not established; never a substitute for zero.'],['Evidence','Recorded information with source and provenance.'],['Provenance','Where a fact came from and whether it is observed, assumed, synthetic or otherwise classified.'],['Lineage','Links between an input, evidence/version and a resulting calculation or decision.'],['Freshness','Whether inputs remain current enough for the current purpose.'],['Stale','A prior result/review no longer matches required current inputs or time context.'],['Fingerprint','A recorded identity of the exact context/version being reviewed or authorized.'],['Idempotency','An identical legitimate retry follows its contract without creating a duplicate action.'],['HUMAN','The actual owner decision through the appropriate canonical workflow.'],['Source approval','Permission for a bounded source read; not permission to select, contact, purchase or publish.'],['Execution authorization','Separate scoped permission for an eligible consequential operation.'],['Synthetic','Test/demo data, not real supplier/marketplace/financial evidence.'],['Read only','A permitted inspection boundary; not a promise that every visible button is safe to execute.'],['NOT_COMPARABLE','Available inputs cannot support a valid comparison under current rules.'],['Readiness','Eligibility for a particular next workflow, not guaranteed market success.'],['Projection','A calculated current view; not necessarily immutable financial history.'],['Reconciliation','Matching records to authoritative external totals or events; not established by a local fake success.'],['Worker','A background service that attempts eligible queued work.'],['Recovery','A controlled response to a recorded failure; not permission to bypass its prerequisites.']
];

